def egcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = egcd(b, a % b)
        return (g, y, x - (a // b) * y)

def common_modulus(n, e1, e2, c1, c2):
    g, s, t = egcd(e1, e2)
    m = (pow(c1, s, n) * pow(c2, t, n)) % n
    return m

m = common_modulus(n, e1, e2, c1, c2)
print(long_to_bytes(m))
